import java.util.*;
import java.nio.*;
public class Main { public static void main(String[] args){ Scanner s=new Scanner(System.in);int n=s.nextInt();ByteBuffer buffer=ByteBuffer.allocate(n*Integer.BYTES);for(int i=0;i<n;i++)buffer.putInt(s.nextInt());buffer.flip();long sum=0;while(buffer.hasRemaining())sum+=buffer.getInt();System.out.println(sum);} }

